    player.library_order.retain(|&id| id != *chosen_id);
    new_state.move_object(*chosen_id, Zone::Hand);
    new_state.log(LogLevel::Event, format!("Searched library and found {}", chosen_name));
    // Shuffle library after searching.
    {
