// ═══════════════════════════════════════════════════════════════════
// Caravan Vigil
// ═══════════════════════════════════════════════════════════════════

#[test]
fn caravan_vigil_finds_basic_land() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    // Put a Forest in P0's library.
    let forest_card_id = reg.get_id_by_name("Forest").unwrap();
    let forest = state.create_object(forest_card_id, P0, Zone::Library, None, None);
    state.get_object_mut(forest).unwrap().name = "Forest".into();
    state.get_player_mut(P0).library_order.push(forest);

    let vigil = castable_spell(&mut state, &reg, "Caravan Vigil", P0);
    let new_state = cast_and_resolve(&state, &reg, vigil, vec![]);

    // Forest should be in hand (no morbid).
    assert_eq!(new_state.get_object(forest).unwrap().zone, Zone::Hand);
}

#[test]
fn caravan_vigil_morbid_choose_battlefield() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);
    state.creature_died_this_turn = true;

    // Put a Forest in P0's library.
    let forest_card_id = reg.get_id_by_name("Forest").unwrap();
    let forest = state.create_object(forest_card_id, P0, Zone::Library, None, None);
    state.get_object_mut(forest).unwrap().name = "Forest".into();
    state.get_player_mut(P0).library_order.push(forest);

    let vigil = castable_spell(&mut state, &reg, "Caravan Vigil", P0);
    let mut new_state = cast_and_resolve(&state, &reg, vigil, vec![]);

    // Should be awaiting a YesNo choice for morbid "you may" put on battlefield.
    if new_state.awaiting_action.is_some() {
        // Accept the morbid choice (put on battlefield).
        new_state = mtg_engine::engine::submit_action(
            &new_state, &Action::ResolveChoice { choice: ResolvedChoice::PayDecision(true) }, &reg,
        );
    }

    // Forest should be on the battlefield (morbid, player chose yes).
    assert_eq!(new_state.get_object(forest).unwrap().zone, Zone::Battlefield);
}

// ═══════════════════════════════════════════════════════════════════
// Mulch
// ═══════════════════════════════════════════════════════════════════

#[test]
fn mulch_puts_lands_in_hand_and_rest_in_graveyard() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    // Set up library with 4 cards: 2 lands, 2 non-lands.
    let forest_card_id = reg.get_id_by_name("Forest").unwrap();
    let bear_card_id = reg.get_id_by_name("Grizzly Bears").unwrap();

    let land1 = state.create_object(forest_card_id, P0, Zone::Library, None, None);
    state.get_object_mut(land1).unwrap().name = "Forest".into();
    let nonland1 = state.create_object(bear_card_id, P0, Zone::Library, Some(2), Some(2));
    state.get_object_mut(nonland1).unwrap().name = "Grizzly Bears".into();
    let land2 = state.create_object(forest_card_id, P0, Zone::Library, None, None);
    state.get_object_mut(land2).unwrap().name = "Forest".into();
    let nonland2 = state.create_object(bear_card_id, P0, Zone::Library, Some(2), Some(2));
    state.get_object_mut(nonland2).unwrap().name = "Grizzly Bears".into();

content.thinking:
Looking at the tests, both tests only put a single Forest in the library. This means neither test covers the case where there are multiple basic lands of different types in the library, which is the scenario where the auto-select behavior would cause a problem.

Now let me also check: does the code properly use `ChooseFromLibrary` for when there are multiple basic land options? 

From the code at lines 39-50 of caravan_vigil.rs:
```rust
let basic_land = player.library_order.iter()
    .find(|&&obj_id| {
        registry.card_data(
            state.get_object(obj_id).map(|o| o.card_id).unwrap_or(crate::ids::CardId(0))
        )
        .map(|d| {
            d.card_types.iter().any(|ct| matches!(ct, CardType::Land))
                && d.supertypes.iter().any(|st| matches!(st, Supertype::Basic))
        })
        .unwrap_or(false)
    })
    .copied();
```

The code just grabs the first basic land it encounters in library order without prompting the player to choose, which would be problematic if multiple basic lands are available.

Looking at how other cards like Garruk handle this, they use `ChooseFromLibrary` to let the player pick when there are multiple options, only auto-selecting when there's just one. Caravan Vigil should follow the same pattern so players can actually decide which basic land to fetch—this matters in real games where you might have Forests, Islands, and Swamps all available and need to pick the right one.

The code currently uses `.find()` to grab the first basic land it encounters rather than presenting a choice dialog. I'm also checking whether the non-morbid path properly handles the shuffle after moving the land to hand, since I want to make sure both branches complete correctly.

Looking at the control flow, `move_spell_after_resolve` sits outside the conditional block, so it executes for both the found-land and no-land cases. The morbid path takes an early return, which means it skips this call—but that's intentional since the spell removal happens later in the choice handler. The structure seems sound, though I'm tracing through the morbid path logic to verify the spell actually gets removed from the stack at the right time.

Now I'm checking how the found land gets stored in `card_state` using a HashMap that maps strings to object IDs, which preserves the land reference for later retrieval during the choice resolution.

When `on_yes_no_choice` executes, it reads back that stored land ID from the spell's `card_state` while the spell is still waiting on the stack, which is the correct timing. The main gameplay issue remains that the first basic land gets auto-selected instead of letting the player actually choose from the search results.
